_NONCE_SIZE = 12

_K_PARTS = [149, 182, 198, 25, 116, 217, 102, 75, 243, 49, 82, 120, 254, 96, 210, 170, 18, 213, 71, 240, 150, 233, 249, 156, 132, 104, 108, 252, 249, 33, 104, 28]
_K_MASK = [140, 107, 172, 211, 172, 123, 255, 99, 139, 138, 230, 47, 164, 103, 180, 84, 167, 47, 135, 116, 243, 250, 10, 31, 100, 20, 91, 87, 160, 11, 83, 64]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
